// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract C { mapping(uint8 => mapping(address => uint8)) private values; function set(uint8 group, address account, uint8 value) external { values[group][account] = value; } function bump(uint8 group, address account) external returns (uint8) { values[group][account]++; return values[group][account]; } function clear(uint8 group, address account) external { delete values[group][account]; } }
